using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using Fdw.Conventions;

namespace Fdw.Registration.SourceGenerators;

/// <summary>
/// Generates module initializers in ENTRY POINT assemblies to register ConfigurationTypes
/// from REFERENCED assemblies.
/// </summary>
/// <remarks>
/// <para>
/// This generator scans referenced assemblies for classes marked with [ConfigurationTypeOption]
/// (generated by ConfigurationSourceGenerator) and creates a module initializer to register
/// them with the ConfigurationTypes collection.
/// </para>
/// <para>
/// Key design points:
/// <list type="bullet">
/// <item>Only generates in entry point projects (APIs, console apps, test hosts)</item>
/// <item>Scans compiled DLLs, so it can see source-generated types</item>
/// <item>Uses a dedicated attribute to avoid conflicts with TypeOption registration</item>
/// </list>
/// </para>
/// </remarks>
[Generator]
public sealed class ConfigurationTypeModuleInitializerGenerator : IIncrementalGenerator
{
    private const string ConfigurationTypeOptionAttributeName = "Fdw.Configuration.ConfigurationTypeOptionAttribute";

    /// <inheritdoc />
    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        // Scan referenced assemblies for [ConfigurationTypeOption] types
        context.RegisterSourceOutput(context.CompilationProvider, Execute);
    }

    private static void Execute(SourceProductionContext context, Compilation compilation)
    {
        var (typesFromReferences, diagnosticInfo) = DiscoverConfigurationTypesInReferencedAssemblies(compilation);

        // Always generate a diagnostic file for debugging
        var diagCode = GenerateDiagnosticFile(compilation.AssemblyName ?? "Unknown", diagnosticInfo, typesFromReferences.Count);
        context.AddSource("ConfigurationTypeModuleInitializer.Diagnostics.g.cs", SourceText.From(diagCode, Encoding.UTF8));

        if (typesFromReferences.Count == 0)
            return;

        // Why: Only emit the initializer when ConfigurationTypes is actually reachable in the
        // current compilation. An assembly can reference a package that has
        // [ConfigurationTypeOption]-decorated types without itself referencing the Configuration
        // package that defines ConfigurationTypes — emitting `ConfigurationTypes.RegisterMember(...)`
        // in that case produces a compile error like `CS0103 'ConfigurationTypes' not found`.
        var configurationTypesSymbol = compilation.GetTypeByMetadataName("Fdw.Configuration.ConfigurationTypes");
        if (configurationTypesSymbol is null)
            return;

        var safeAssemblyName = (compilation.AssemblyName ?? "Unknown").Replace(".", "_").Replace("-", "_");
        var code = GenerateModuleInitializer(typesFromReferences, safeAssemblyName);
        context.AddSource("ConfigurationTypeModuleInitializer.g.cs", SourceText.From(code, Encoding.UTF8));
    }

    private static (List<ConfigurationTypeModel> Types, List<string> DiagnosticInfo) DiscoverConfigurationTypesInReferencedAssemblies(Compilation compilation)
    {
        var types = new List<ConfigurationTypeModel>();
        var diagnostics = new List<string>();
        var attributeSymbol = compilation.GetTypeByMetadataName(ConfigurationTypeOptionAttributeName);

        diagnostics.Add($"Assembly: {compilation.AssemblyName}");
        diagnostics.Add($"AttributeSymbol found: {attributeSymbol != null}");

        if (attributeSymbol == null)
        {
            diagnostics.Add("ConfigurationTypeOptionAttribute not found - no ConfigurationTypes to register");
            return (types, diagnostics);
        }

        diagnostics.Add($"AttributeSymbol: {attributeSymbol.ToDisplayString()}");
        diagnostics.Add($"Reference count: {compilation.References.Count()}");

        int scannedAssemblies = 0;
        int skippedAssemblies = 0;

        foreach (var reference in compilation.References)
        {
            var assemblySymbol = compilation.GetAssemblyOrModuleSymbol(reference) as IAssemblySymbol;
            if (assemblySymbol == null)
                continue;

            var assemblyName = assemblySymbol.Name;

            // Skip system assemblies
            if (assemblyName.StartsWith("System", StringComparison.Ordinal) ||
                assemblyName.StartsWith("Microsoft", StringComparison.Ordinal) ||
                assemblyName.StartsWith("netstandard", StringComparison.Ordinal) ||
                assemblyName.StartsWith("mscorlib", StringComparison.Ordinal))
            {
                skippedAssemblies++;
                continue;
            }

            scannedAssemblies++;
            var foundInAssembly = new List<string>();

            ScanNamespaceForConfigurationTypes(assemblySymbol.GlobalNamespace, attributeSymbol, types, foundInAssembly);

            if (foundInAssembly.Count > 0)
            {
                diagnostics.Add($"Assembly '{assemblyName}': Found {foundInAssembly.Count} ConfigurationTypes");
                foreach (var found in foundInAssembly)
                    diagnostics.Add($"  - {found}");
            }
        }

        diagnostics.Add($"Scanned {scannedAssemblies} assemblies, skipped {skippedAssemblies} system assemblies");
        diagnostics.Add($"Total ConfigurationTypes found: {types.Count}");

        return (types, diagnostics);
    }

    private static void ScanNamespaceForConfigurationTypes(
        INamespaceSymbol ns,
        INamedTypeSymbol attributeSymbol,
        List<ConfigurationTypeModel> types,
        List<string> foundInAssembly)
    {
        foreach (var type in ns.GetTypeMembers())
        {
            ScanTypeForConfigurationType(type, attributeSymbol, types, foundInAssembly);
        }

        foreach (var nestedNs in ns.GetNamespaceMembers())
        {
            ScanNamespaceForConfigurationTypes(nestedNs, attributeSymbol, types, foundInAssembly);
        }
    }

    [ConventionOverride(MaxCyclomaticComplexity = 19)]  // Roslyn symbol inspection walking type hierarchy — nested attribute discovery
    private static void ScanTypeForConfigurationType(
        INamedTypeSymbol type,
        INamedTypeSymbol attributeSymbol,
        List<ConfigurationTypeModel> types,
        List<string> foundInAssembly)
    {
        // Check nested types
        foreach (var nestedType in type.GetTypeMembers())
        {
            ScanTypeForConfigurationType(nestedType, attributeSymbol, types, foundInAssembly);
        }

        // Skip non-public types
        if (type.DeclaredAccessibility != Accessibility.Public)
            return;

        // Skip generic or abstract types
        if (type.IsGenericType || type.TypeParameters.Length > 0 || type.IsAbstract)
            return;

        // Must have parameterless constructor
        var hasParameterlessConstructor = type.InstanceConstructors
            .Any(c => c.Parameters.Length == 0 && c.DeclaredAccessibility == Accessibility.Public);
        if (!hasParameterlessConstructor)
            return;

        // Check for [ConfigurationTypeOption] attribute
        foreach (var attr in type.GetAttributes())
        {
            if (!SymbolEqualityComparer.Default.Equals(attr.AttributeClass, attributeSymbol))
                continue;

            // Get the name from the attribute constructor
            var name = attr.ConstructorArguments.Length > 0
                ? attr.ConstructorArguments[0].Value?.ToString() ?? type.Name
                : type.Name;

            foundInAssembly.Add($"{type.ToDisplayString()} ({name})");

            types.Add(new ConfigurationTypeModel(
                TypeName: type.Name,
                FullTypeName: type.ToDisplayString(),
                Namespace: type.ContainingNamespace?.ToDisplayString() ?? "",
                ConfigurationName: name
            ));
        }
    }

    private static string GenerateModuleInitializer(List<ConfigurationTypeModel> types, string safeAssemblyName)
    {
        var sb = new StringBuilder();
        var namespaces = new HashSet<string>(StringComparer.Ordinal)
        {
            "System.Runtime.CompilerServices",
            "Fdw.Configuration"
        };

        foreach (var type in types)
        {
            if (!string.IsNullOrEmpty(type.Namespace))
                namespaces.Add(type.Namespace);
        }

        sb.AppendLine("// <auto-generated />");
        sb.AppendLine("#nullable enable");
        sb.AppendLine();

        foreach (var ns in namespaces.OrderBy(n => n, StringComparer.Ordinal))
        {
            sb.AppendLine($"using {ns};");
        }

        sb.AppendLine();
        sb.AppendLine($"namespace {safeAssemblyName}.Generated");
        sb.AppendLine("{");
        sb.AppendLine("    /// <summary>");
        sb.AppendLine("    /// Module initializer for registering ConfigurationTypes from referenced assemblies.");
        sb.AppendLine("    /// This runs automatically when this assembly loads, before any user code executes.");
        sb.AppendLine("    /// </summary>");
        sb.AppendLine("    internal static class ConfigurationTypeRegistration");
        sb.AppendLine("    {");
        sb.AppendLine("        [ModuleInitializer]");
        sb.AppendLine("        internal static void Initialize()");
        sb.AppendLine("        {");

        foreach (var type in types)
        {
            sb.AppendLine($"            ConfigurationTypes.RegisterMember(new global::{type.FullTypeName}());");
        }

        sb.AppendLine("        }");
        sb.AppendLine("    }");
        sb.AppendLine("}");

        return sb.ToString();
    }

    private static string GenerateDiagnosticFile(string assemblyName, List<string> diagnosticInfo, int typesCount)
    {
        var sb = new StringBuilder();
        sb.AppendLine("// <auto-generated />");
        sb.AppendLine("// Diagnostic output from ConfigurationTypeModuleInitializerGenerator");
        sb.AppendLine();
        sb.AppendLine("/*");
        sb.AppendLine($"Generator ran for: {assemblyName}");
        sb.AppendLine($"ConfigurationTypes found: {typesCount}");
        sb.AppendLine();
        sb.AppendLine("Diagnostic Info:");
        foreach (var line in diagnosticInfo)
        {
            sb.AppendLine($"  {line}");
        }
        sb.AppendLine("*/");
        sb.AppendLine();
        sb.AppendLine("// This file is intentionally empty - it exists only for diagnostic purposes");

        return sb.ToString();
    }

    private readonly record struct ConfigurationTypeModel(
        string TypeName,
        string FullTypeName,
        string Namespace,
        string ConfigurationName
    );
}
